def fitg(g):
    A=np.column_stack([np.ones_like(t),g,t,P,t*P,P**2,t*P**2,g*P,g*P**2,g*P**3,t*g,P**3,t*P**3])
    c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return np.mean((A@c-dP_dt)**2)/np.var(dP_dt), c
forms={}
